public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (dist[u] != Integer.MAX_VALUE && dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
            }
        }
    }
    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += dist[i];
        }
    }
    return totalTime;
}

