public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int min = arr[0];
    int max = arr[n - 1];
    int count = 0;
    while (min < max) {
        for (int i = 0; i < n; i++) {
            if (arr[i] < min) {
                arr[i] += 1;
                count++;
            } else if (arr[i] > max) {
                arr[i] -= 1;
                count++;
            }
        }
        min = arr[0];
        max = arr[n - 1];
    }
    return count;
}

